const config = $input.first().json;
const [owner, repo] = String(config.githubRepo || '').split('/');
if (!owner || !repo) {
  throw new Error('Set GITHUB_REPO as owner/repo');
}
if (!config.destinationWebhookUrl) {
  throw new Error('Set DESTINATION_WEBHOOK_URL to a Discord webhook URL');
}
const language = String(config.language || 'EN').toUpperCase() === 'FR' ? 'FR' : 'EN';
const now = new Date();
const since = new Date(now);
since.setDate(now.getDate() - 7);
const sinceIso = since.toISOString();
const untilIso = now.toISOString();
const dateOnly = (date) => date.toISOString().slice(0, 10);
const authToken = $env.GITHUB_TOKEN;
const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-dev-summary'
};
if (authToken) {
  headers.Authorization = `Bearer ${authToken}`;
}
const api = 'https://api.github.com';
const request = async (url) => await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
const commitsUrl = `${api}/repos/${owner}/${repo}/commits?since=${encodeURIComponent(sinceIso)}&until=${encodeURIComponent(untilIso)}&per_page=100`;
const closedIssuesQuery = encodeURIComponent(`repo:${owner}/${repo} is:issue is:closed closed:${dateOnly(since)}..${dateOnly(now)}`);
const mergedPrsQuery = encodeURIComponent(`repo:${owner}/${repo} is:pr is:merged merged:${dateOnly(since)}..${dateOnly(now)}`);
const [commits, closedIssuesResult, mergedPrsResult] = await Promise.all([
  request(commitsUrl),
  request(`${api}/search/issues?q=${closedIssuesQuery}&per_page=100`),
  request(`${api}/search/issues?q=${mergedPrsQuery}&per_page=100`)
]);
const summarizeCommit = (commit) => ({
  sha: commit.sha?.slice(0, 7),
  message: commit.commit?.message?.split('\n')[0],
  author: commit.commit?.author?.name,
  url: commit.html_url
});
const summarizeIssue = (issue) => ({
  number: issue.number,
  title: issue.title,
  author: issue.user?.login,
  closedAt: issue.closed_at,
  url: issue.html_url
});
return [{
  json: {
    owner,
    repo,
    language,
    destinationWebhookUrl: config.destinationWebhookUrl,
    period: { since: sinceIso, until: untilIso },
    commits: commits.map(summarizeCommit),
    closedIssues: (closedIssuesResult.items || []).map(summarizeIssue),
    mergedPullRequests: (mergedPrsResult.items || []).map(summarizeIssue)
  }
}];

const activity = $input.first().json;
const languageInstruction = activity.language === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';
const prompt = `You are preparing a weekly engineering update for ${activity.owner}/${activity.repo}. ${languageInstruction}\n\nSummarize the week as a narrative, not as a raw changelog. Mention themes, notable merged work, important closed issues, and follow-up risks. Keep it concise enough for a Discord announcement.\n\nPeriod: ${activity.period.since} to ${activity.period.until}\n\nCommits:\n${JSON.stringify(activity.commits, null, 2)}\n\nClosed issues:\n${JSON.stringify(activity.closedIssues, null, 2)}\n\nMerged pull requests:\n${JSON.stringify(activity.mergedPullRequests, null, 2)}`;
return [{
  json: {
    destinationWebhookUrl: activity.destinationWebhookUrl,
    owner: activity.owner,
    repo: activity.repo,
    period: activity.period,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const claude = $input.first().json;
const text = Array.isArray(claude.content)
  ? claude.content.map((part) => part.text || '').join('\n').trim()
  : String(claude.text || '').trim();
const workflowData = $('Build Claude Request').first().json;
if (!text) {
  throw new Error('Claude response did not include summary text');
}
return [{
  json: {
    destinationWebhookUrl: workflowData.destinationWebhookUrl,
    discordPayload: {
      username: 'Weekly Dev Summary',
      content: `## Weekly summary for ${workflowData.owner}/${workflowData.repo}\n${text}`
    }
  }
}];
